import math

def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    rank = 0
    for i in range(m):
        if rank == n:
            break
        pivot_row = i
        while pivot_row < m and A[pivot_row][i] == 0:
            pivot_row += 1
        if pivot_row == m:
            continue
        A[i], A[pivot_row] = A[pivot_row], A[i]
        for j in range(m):
            if j != i:
                factor = -A[j][i] / A[i][i]
                for k in range(n):
                    if k < i:
                        A[j][k] += factor * A[i][k]
                    elif k > i:
                        A[j][k] -= factor * A[i][k]
        rank += 1
    return rank

def matrix_multiplication(A, B):
    m = len(A)
    n = len(B[0])
    p = len(B)
    C = [[0 for _ in range(n)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][j] += A[i][k] * B[k][j]
    return C

def determinant(A):
    m, n = len(A), len(A[0])
    if m != n:
        raise ValueError("Matrix must be square")
    if n == 1:
        return A[0][0]
    det = 0
    for j in range(n):
        submatrix = [row[:j] + row[j+1:] for row in A[1:]]
        det += (-1) ** j * A[0][j] * determinant(submatrix)
    return det

def rank(matrix):
    return gaussian_elimination(matrix)

def create_tropical_matrix(clauses, variables):
    m = len(clauses)
    n = len(variables)
    matrix = [[0 for _ in range(n)] for _ in range(m)]
    for i, clause in enumerate(clauses):
        for literal in clause:
            if literal[0] == 'x':
                var_index = int(literal[1:]) - 1
                matrix[i][var_index] = max(matrix[i][var_index], literal[2:])
            elif literal[0] == '~':
                var_index = int(literal[1:]) - 1
                matrix[i][var_index] = max(matrix[i][var_index], literal[3:])
    return matrix

def dpll_depth(clauses, variables):
    def solve(clauses, assignment):
        if not clauses:
            return True
        clause = next((c for c in clauses if any(l in assignment for l in c)), None)
        if not clause:
            return False
        literal = next(l for l in clause if l in assignment)
        if literal[0] == '~':
            literal = literal[1:]
            negated = True
        else:
            negated = False
        var_index = int(literal[1:]) - 1
        if assignment[var_index] != negated:
            return solve(clauses, assignment)
        assignment[var_index] = not negated
        if solve(clauses, assignment):
            return True
        assignment[var_index] = negated
        return False
    return len(solve(clauses, [False] * len(variables)))

